mapper.select:
SELECT * FROM ( SELECT ROWNUM rn, a.* FROM ( SELECT p.post_id, p.user_id, p.title, p.content, p.thumbnail_image, p.category, p.country, p.view_count, p.like_count, p.comment_count, p.created_at, p.updated_at, p.deleted_at,
-- 작성자 정보 u.user_id as user_user_id, u.email as user_email, u.name as user_name, u.nickname as user_nickname, u.profile_img as user_profile_img
FROM posts p LEFT JOIN users u ON p.user_id = u.user_id WHERE p.deleted_at IS NULL
AND p.category = #{category}
AND p.country = #{country}
AND p.title LIKE '%' || #{searchKeyword} || '%'
AND p.content LIKE '%' || #{searchKeyword} || '%'
AND (u.name LIKE '%' || #{searchKeyword} || '%' OR u.nickname LIKE '%' || #{searchKeyword} || '%')
AND (p.title LIKE '%' || #{searchKeyword} || '%' OR p.content LIKE '%' || #{searchKeyword} || '%')
AND p.user_id = #{userId}
ORDER BY
p.view_count DESC, p.post_id DESC p.like_count DESC, p.post_id DESC p.created_at DESC, p.post_id DESC
) a WHERE ROWNUM <= #{offset} + #{size} ) WHERE rn > #{offset}

SELECT COUNT(*) FROM posts p LEFT JOIN users u ON p.user_id = u.user_id WHERE p.deleted_at IS NULL
AND p.category = #{category}
AND p.country = #{country}
AND p.title LIKE '%' || #{searchKeyword} || '%'
AND p.content LIKE '%' || #{searchKeyword} || '%'
AND (u.name LIKE '%' || #{searchKeyword} || '%' OR u.nickname LIKE '%' || #{searchKeyword} || '%')
AND (p.title LIKE '%' || #{searchKeyword} || '%' OR p.content LIKE '%' || #{searchKeyword} || '%')
AND p.user_id = #{userId}

SELECT * FROM ( SELECT ROWNUM rn, a.* FROM ( SELECT p.post_id, p.user_id, p.title, p.content, p.thumbnail_image, p.category, p.country, p.view_count, p.like_count, p.comment_count, p.created_at, p.updated_at, p.deleted_at,
-- 작성자 정보 u.user_id as user_user_id, u.email as user_email, u.name as user_name, u.nickname as user_nickname, u.profile_img as user_profile_img
FROM posts p LEFT JOIN users u ON p.user_id = u.user_id WHERE p.deleted_at IS NULL AND p.category = #{category} ORDER BY p.created_at DESC, p.post_id DESC ) a WHERE ROWNUM <= #{offset} + #{size} ) WHERE rn > #{offset}

SELECT p.post_id, p.user_id, p.title, p.content, p.thumbnail_image, p.category, p.country, p.view_count, p.like_count, p.comment_count, p.created_at, p.updated_at, p.deleted_at,
-- 작성자 정보 u.user_id as user_user_id, u.email as user_email, u.name as user_name, u.nickname as user_nickname, u.profile_img as user_profile_img
FROM posts p LEFT JOIN users u ON p.user_id = u.user_id WHERE p.post_id = #{postId}

mapper.update:
UPDATE posts
SET like_count = (
    SELECT COUNT(*)
    FROM post_like
    WHERE post_id = #{postId}
)
WHERE post_id = #{postId}

UPDATE posts
SET comment_count = (
    SELECT COUNT(*)
    FROM comments
    WHERE post_id = #{postId}
      AND deleted_at IS NULL
)
WHERE post_id = #{postId}

mapper.select:
SELECT * FROM ( SELECT ROWNUM rn, a.* FROM ( SELECT p.post_id, p.user_id, p.title, p.content, p.thumbnail_image, p.category, p.country, p.view_count, p.like_count, p.comment_count, p.created_at, p.updated_at, p.deleted_at,
-- 작성자 정보 u.user_id as user_user_id, u.email as user_email, u.name as user_name, u.nickname as user_nickname, u.profile_img as user_profile_img
FROM posts p LEFT JOIN users u ON p.user_id = u.user_id WHERE p.deleted_at IS NULL
AND p.created_at >= SYSDATE - #{periodDays}
AND p.category = #{category}
AND p.title LIKE '%' || #{searchKeyword} || '%'
AND p.content LIKE '%' || #{searchKeyword} || '%'
AND (u.name LIKE '%' || #{searchKeyword} || '%' OR u.nickname LIKE '%' || #{searchKeyword} || '%')
AND (p.title LIKE '%' || #{searchKeyword} || '%' OR p.content LIKE '%' || #{searchKeyword} || '%')
ORDER BY (NVL(p.view_count, 0) * 2 + NVL(p.like_count, 0) * 3 + NVL(p.comment_count, 0) * 1) DESC, p.created_at DESC, p.post_id DESC ) a WHERE ROWNUM <= #{offset} + #{size} ) WHERE rn > #{offset}
